import pytest
import asyncio
import uuid
from concurrent.futures import ThreadPoolExecutor
from fastapi.testclient import TestClient

from app.main import app


@pytest.mark.asyncio
class TestConcurrentBookings:

    def test_concurrent_booking_same_seat(self, client, db, sample_event, sample_seats, redis_client,
                                          mock_event_publisher):
        """Test that only one booking succeeds when multiple users try to book the same seat"""
        seat = sample_seats[0]
        num_users = 10

        def attempt_booking(user_id: str):
            response = client.post(
                "/api/v1/bookings/",
                json={
                    "user_id": user_id,
                    "event_id": str(sample_event.event_id),
                    "seat_id": str(seat.seat_id)
                }
            )
            return response.status_code, response.json()

        # Create multiple users trying to book simultaneously
        with ThreadPoolExecutor(max_workers=num_users) as executor:
            futures = [
                executor.submit(attempt_booking, str(uuid.uuid4()))
                for _ in range(num_users)
            ]

            results = [future.result() for future in futures]

        # Count successes
        successes = sum(1 for status, _ in results if status == 201)
        conflicts = sum(1 for status, _ in results if status == 409)

        # Only one should succeed
        assert successes == 1
        assert conflicts == num_users - 1

    def test_concurrent_booking_different_seats(self, client, sample_event, sample_seats, redis_client,
                                                mock_event_publisher):
        """Test that multiple users can book different seats simultaneously"""
        num_users = len(sample_seats)

        def attempt_booking(index: int):
            response = client.post(
                "/api/v1/bookings/",
                json={
                    "user_id": str(uuid.uuid4()),
                    "event_id": str(sample_event.event_id),
                    "seat_id": str(sample_seats[index].seat_id)
                }
            )
            return response.status_code

        with ThreadPoolExecutor(max_workers=num_users) as executor:
            futures = [
                executor.submit(attempt_booking, i)
                for i in range(num_users)
            ]

            results = [future.result() for future in futures]

        # All should succeed since they're booking different seats
        successes = sum(1 for status in results if status == 201)
        assert successes == num_users
